te":DateFormat('yyyy-MM-dd').format(DateTime.now()),"odo":odo.text,"repair":rep.text.isEmpty?'صيانة دورية':rep.text,"parts":parts.text,"invoice":inv.text,"cost":cost.text.isEmpty?'0':cost.text,"oil":oil})); _save(); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم حفظ سجل الصيانة ✅'))); },child:const Text('💾 حفظ سجل الصيانة',style:TextStyle(fontSize:20,color:Colors.black,fontWeight:FontWeight.bold))))])))); }
