  Widget _syncPage(Color gold){ final codeCtrl=TextEditingController(); return Padding(padding:const EdgeInsets.all(14),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('🔄 مزامنة عدة أجهزة',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('الخطوة 1: في الجهاز الأول اضغط إنشاء كود وانسخه\nالخطوة 2: في الجهاز الثاني الصق الكود هنا واضغط استيراد',style:TextStyle(color:Colors.white70)),const SizedBox(height:14),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:gold,padding:const EdgeInsets.all(16)),onPressed:(){ codeCtrl.text=syncCode(); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إنشاء كود المزامنة - انسخه الآن'))); },child:const Text('📋 إنشاء كود مزامنة',style:TextStyle(color:Colors.black,fontWeight:FontWeight.bold,fontSize:18))),const SizedBox(height:12),TextField(controller:codeCtrl,maxLines:6,decoration:const InputDecoration(hintText:'الصق كود المزامنة هنا...',filled:true,fillColor:Colors.white,border:OutlineInputBorder())),const SizedBox(height:12),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.green,padding:const EdgeInsets.all(16)),onPressed:()=>importCode(codeCtrl.text),child:const Text('✅ استيراد ومزامنة',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:18))),const SizedBox(height:20),const Text('حد تنبيه الزيت (كم)',style:TextStyle(color:Colors.white)),Slider(value:oilLimit.toDouble(),min:1000,max:10000,divisions:9,onChanged:(v)=>setState(()=>oilLimit=v.toInt()),onChangeEnd:(v)=>_save()),Text('$oilLimit كم',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold))]))); }
